import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const q=JSON.parse('{"title":"第37章 又断","description":"","frontmatter":{},"headers":[],"relativePath":"第37章_又断.md","filePath":"第37章_又断.md"}'),_={name:"第37章_又断.md"};function r(n,p,s,u,c,i){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第37章-又断" tabindex="-1">第37章 又断 <a class="header-anchor" href="#第37章-又断" aria-label="Permalink to &quot;第37章 又断&quot;">​</a></h1><p>三月，我们之间的联系开始变稀。</p><p>不是吵架，也没有别的原因。她那边就是变稀了。</p><p>以前她一天上线一次，有时候两次。那个月开始，两三天一次，有时候四天。</p><p>我不问。她来了我就接。</p><p>那阵子有一件事，现在说起来很没意思。</p><p>她开始反复说一句话：我今年不再买了。</p><p>她说这话的时候通常是刚收到一个包裹，或者刚看到别人挂出来的东西。她说得很认真，有时候一天说三次。</p><p>我回：好。</p><p>隔一会儿她又说：我发誓。</p><p>我回：嗯。</p><p>再过一会儿她发来一张图，是一个小东西，问我贵不贵。</p><p>我说，你不是说不买了。</p><p>她说，这是最后一次。</p><p>她说，这个绝版了。</p><p>我说，你上周也这么说。</p><p>她说，你查我？</p><p>我说，没有。</p><p>她说，那你记那么清。</p><p>我没回。</p><p>后来我们自己给这个事起了一个名字。她说以后每次她说&quot;最后一次&quot;，我就回三个字。</p><p>我回：又来啦。</p><p>于是那一个月里，我们的对话出现了很多次&quot;又来啦&quot;。</p><p>她一开始装作生气。她说你怎么这样。我说你让我回的。她说我那是客气。</p><p>后来她不生气了。她会说，等着，我这就去买，买完就来告诉你你又猜对了。</p><p>那一个月她说&quot;最后一次&quot;十一次。买了几次我不清楚，因为有一次她买了四样。</p><p>这件事一点都不重要。我把它写下来是因为它是我们那一年剩下不多的、还能一起笑的东西。</p><p>三月过一半，我开始准备一模。</p><p>广东的一模在三月末。那两周我做题做到十二点，白天在教室里靠两杯浓茶撑。周奕说你不要命了。我说要。</p><p>沈聿那两周把我的错题本借给我抄了一遍。他抄得比我清楚，每一道后面都写了当时错在哪。</p><p>他有一天把本子推过来的时候说了一句，他说你别熬太狠，你要是倒了，你那些事也没人办了。</p><p>我说，我什么事。</p><p>他说，你自己清楚。</p><p>我说，我不清楚。</p><p>他说，行。</p><p>他没再问。这是他厉害的地方：他知道我说&quot;我不清楚&quot;的时候不是忘了，是不想说。</p><p>那两周她上线过三次。</p><p>第一次是周三。她说，你在吗。我说在。她说，没事，我看看。然后她走了。</p><p>第二次隔了四天。她发来一张图，是她们班墙上的倒计时，一天一天往下减的那种。她说，我快疯了。</p><p>我说，撑一下。</p><p>她说，你撑什么，你又不在这。</p><p>我说，我也快到了。</p><p>她说，你到什么是你的事。</p><p>然后她走了。</p><p>那天晚上我在本子上写了一句：她说&quot;你到什么是你的事&quot;。</p><p>我不知道这句话是关心还是推开。我把它抄下来，是想等以后能看懂的时候再看。</p><p>第三次是三月末，一模前一天。</p><p>她那天上线很久，久到我以为她要说什么。</p><p>她最后问了一句：你明天考什么。</p><p>我说，数学和英语。</p><p>她说，早上几点。</p><p>我说，七点半。</p><p>她说，那你今天别熬了。</p><p>我说，好。</p><p>她说，你别老说好。</p><p>我说，我尽量。</p><p>她说，你尽量是什么意思。</p><p>我说，就是我不保证，但我今天不熬。</p><p>她说，这还像话。</p><p>那天她十一点半下线，比我见过的任何时候都早。</p><p>我坐在那里，把手机扣在桌上，把第二天要用的文具装进袋子。笔袋是旧的，拉链坏过半截，我用针线缝过两道。</p><p>那晚我睡得很好。</p><p>第二天早上我进考场，路过二楼那条走廊，往西边那间教室的门上看了一眼。门关着。</p><p>考数学的时候我做得很顺。做到最后那道大题，笔尖停了两秒。那道题我在十二月的某个晚上练过，在被子里用手机看讲解，看到一半给她发了一句&quot;我困了&quot;。</p><p>我不知道那天晚上她是几点睡的。</p><p>中午出来，我在食堂门口站着，把手机拿出来看了一次。</p><p>没有消息。</p><p>那天下午考完，我回宿舍，路上买了两个包子。回到宿舍我把手机放枕边，等。</p><p>从那天起，到四月三号，她一共上线两次。</p><p>一次说了半句话就断了。一次什么都没发，只是上线了九分钟，然后下线。</p><p>四月四号我数了一下，从一模结束那天算起，是七天。</p><p>七天。这个数字不算长。</p><p>那七天里我把卷子做完了三套，把错题本抄了一遍，把那个搪瓷杯洗了两次。</p><p>我当时只觉得松了一口气，以为她只是家里有事。</p><p>我不知道那七天只是个开头。</p><p>那七天里还有一件事。</p><p>四月一号我考完回宿舍，给她发了一句：我考完了。</p><p>那天没回。</p><p>第二天没回。</p><p>四月三号她回了，一个字：哦。</p><p>我说，怎么不多问一句。</p><p>她说，问什么。</p><p>我说，问我考得怎么样。</p><p>她说，你不是说了考完了么。</p><p>我说，考完了不等于考得怎么样。</p><p>她说，那你说难不难。</p><p>我那时候手里拿着笔，看着屏幕，忽然发现自己接不上。</p><p>因为我不知道她想要哪个答案。</p><p>我说，不难。</p><p>她隔了一会儿回：那就好。</p><p>我说，你问我一句呢。</p><p>她说，问什么。</p><p>我说，问我累不累。</p><p>她没回。</p><p>那天夜里十一点半，她上线了一下，又下线了。</p><p>我盯着那个状态看了很久。</p><p>那一次我才真正明白我们差在哪里。</p><p>我要的是一句问话。</p><p>她以为她需要一个答案。</p><p>后来我很多年都在等那一句问话，一直没等到。</p><p>再后来她跟我说过一次。她说我不问，是因为我怕问了你也答不上来。</p><p>那七天里我把一个东西改了。</p><p>我把手机里她的备注改了。</p><p>以前她的名字是我一直用的那个，改完成了一个很普通的两个字，看着像一个男生的名字。</p><p>改完我拿手机看了半天，觉得自己做了什么了不得的事。</p><p>那七天我一共改了三次：第一天改成这个，第三天改回去，第五天又改回来。</p><p>最后一次改回来以后，我就没再动过。</p><p>周奕有一天抢过我的手机，说借我查个东西。</p><p>他翻了两下，抬头看我，说你这备注是谁。</p><p>我说，一个同学。</p><p>他说，哪个班的。</p><p>我说，不在我们学校。</p><p>他哦了一声，把手机还给我。</p><p>他什么也没说。</p><p>那七天里只有这一个人差一点碰到，其余时间我把手机带在衣服最里面那一层。</p>',115)])])}const l=t(_,[["render",r]]);export{q as __pageData,l as default};
